def _parse_decimal(value: object) -> int | None:
    """Strict non-negative decimal parse; None when malformed.

    Only ``0`` or a digit string whose first digit is non-zero is accepted:
    leading zeros, signs, whitespace and non-string types are all rejected.
    """
    if not isinstance(value, str) or not value:
        return None
    if value != "0" and (not value.isdigit() or value[0] == "0"):
        return None
    return int(value)


def _parse_ascii_decimal(value: object) -> int | None:
    """Like ``_parse_decimal`` but restricted to ASCII digits.

    ``str.isdigit`` also accepts non-ASCII digits (Arabic-Indic, superscripts
    and the like) that ``int`` then converts; the transaction-index range
    parameters reject those outright.
    """
    if not isinstance(value, str) or not value or not value.isascii():
        return None
    return _parse_decimal(value)


